def compute_plim(C, st, K):
    if st['topology'] == 'iv':
        FS_star = C @ st['FS']
        if abs(FS_star[1]) < 1e-8:
            return np.nan
        return st['RF'] / FS_star[1]
    elif st['topology'] == 'exposure':
        q = C @ st['p_A']
        cy = C @ st['E_YD']
        EZZ = np.zeros((K, K))
        EZZ[0, 0] = 1.0
        for j in range(1, K):
            EZZ[0, j] = EZZ[j, 0] = q[j]
            EZZ[j, j] = q[j]
        EZY = np.zeros(K)
        EZY[0] = st['E_Y']
        for j in range(1, K):
            EZY[j] = cy[j]
        try:
            return np.linalg.solve(EZZ, EZY)
        except np.linalg.LinAlgError:
            return np.full(K, np.nan)
    else:
        q = C @ st['p_A']
        ct = C @ st['E_TD']
        cy = C @ st['E_YD']
        dim = K + 1
        EZZ = np.zeros((dim, dim))
        EZZ[0, 0] = 1.0
        EZZ[0, 1] = EZZ[1, 0] = st['E_T']
        EZZ[1, 1] = st['E_T2']
        for j in range(1, K):
            EZZ[0, j + 1] = EZZ[j + 1, 0] = q[j]
            EZZ[1, j + 1] = EZZ[j + 1, 1] = ct[j]
            EZZ[j + 1, j + 1] = q[j]
        EZY = np.zeros(dim)
        EZY[0] = st['E_Y']
        EZY[1] = st['E_TY']
        for j in range(1, K):
            EZY[j + 1] = cy[j]
        try:
            return np.linalg.solve(EZZ, EZY)
        except np.linalg.LinAlgError:
            return np.full(dim, np.nan)


